import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8IeflXD.js";var i=JSON.parse(`{"title":"Million-row sheet","description":"","frontmatter":{},"headers":[],"relativePath":"showcase-sheet.md","filePath":"pages/showcase-sheet.md"}`),a={name:`showcase-sheet.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="million-row-sheet" tabindex="-1">Million-row sheet <a class="header-anchor" href="#million-row-sheet" aria-label="Permalink to “Million-row sheet”">​</a></h1><p>One million rows and 240 columns, both seats of the window switched on, and the rows minted from their index rather than stored.</p><p><a href="./demo/sheet" target="_blank" rel="noreferrer">Open the route full screen</a></p><h2 id="what-it-is-stressing" tabindex="-1">What it is stressing <a class="header-anchor" href="#what-it-is-stressing" aria-label="Permalink to “What it is stressing”">​</a></h2><p>240,000,000 cells exist in the model. 308 of them stand in the document at the viewport this route&#39;s own chromium test mounts, which is 22 rows by 14 columns. A grid that windows only rows would put 240 cells in the document per rendered row and drop frames the moment the scroll went sideways.</p><h2 id="where-the-rows-come-from" tabindex="-1">Where the rows come from <a class="header-anchor" href="#where-the-rows-come-from" aria-label="Permalink to “Where the rows come from”">​</a></h2><p><code>demo/5_sheet.ts</code> hands <code>grid()</code> a proxy over an empty array: <code>length</code> answers 1,000,000 and an index answers <code>{ id, at }</code> built on the spot. <code>Array.isArray</code> still holds and <code>map</code> still walks it, so no array of a million objects is ever held by the demo.</p><p>Every cell value is a function of the row&#39;s index and the column&#39;s, so the 240,000,000 values exist without one of them being stored.</p><h2 id="what-the-panel-reports" tabindex="-1">What the panel reports <a class="header-anchor" href="#what-the-panel-reports" aria-label="Permalink to “What the panel reports”">​</a></h2><table tabindex="0"><thead><tr><th>readout</th><th>what it answers</th></tr></thead><tbody><tr><td>rows, columns, cells</td><td>the size of the model</td></tr><tr><td>rendered rows, columns, cells</td><td>the size of the document</td></tr><tr><td>model cells per rendered cell</td><td>the ratio those two make</td></tr><tr><td>frames per second</td><td>sampled every 500 ms off <code>requestAnimationFrame</code></td></tr><tr><td>scroller height</td><td>the pixels the spacer asks for, against the engine&#39;s ceiling</td></tr></tbody></table><h2 id="the-ceiling-this-route-pins-itself-to" tabindex="-1">The ceiling this route pins itself to <a class="header-anchor" href="#the-ceiling-this-route-pins-itself-to" aria-label="Permalink to “The ceiling this route pins itself to”">​</a></h2><p>A million rows at the standard 36 px density asks a scroller for 36,000,000 px, and the engine stops near 33,554,432. The route runs at compact, 28 px, for a 28,000,028 px scroller, and offers no density control, because switching to comfortable would put the last rows out of reach of the scrollbar.</p><h2 id="what-it-costs" tabindex="-1">What it costs <a class="header-anchor" href="#what-it-costs" aria-label="Permalink to “What it costs”">​</a></h2><p>Measured by the probe in <code>scripts/stats.mjs</code>, run at both counts with the rows pre-allocated so the two are comparable: 126.5 bytes retained per row at 100,000 rows, 114.7 at 1,000,000. The figure holds, and it falls slightly, because the fixed cost of one grid is spread over ten times the rows.</p><h2 id="what-holds-it-up" tabindex="-1">What holds it up <a class="header-anchor" href="#what-holds-it-up" aria-label="Permalink to “What holds it up”">​</a></h2><p><code>demo/5_sheet.test.ts</code> mounts this route in chromium, scrolls it to eight stops including both far corners, and asserts the rendered cell count stays under 1,200 at every one of them while the first rendered row keeps changing.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to “Related pages”">​</a></h2><p><a href="/hafley-rxjs/signal-grid/view-virtualize">Virtualization</a> for the two seats and the state key behind them, and <a href="/hafley-rxjs/signal-grid/why-seats">The seat table</a> for why one windowing serves both.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};